let errors = $state<{ claimCode?: string; email?: string; handle?: string; password?: string }>(
  {}
);

let selectedDid = $state<string | null>(null);
let selectedDidDoc = $state<Record<string, unknown> | null>(null);
let selectedDeviceKeyIsRoot = $state<boolean | null>(null);
// The selected identity's device key is gone from the Secure Enclave; the detail
// screen explains the signing entries it is already withholding.
let selectedDeviceKeyUnusable = $state(false);

let selectedAlertDid = $state<string | null>(null);
let selectedAlertChanges = $state<UnauthorizedChange[]>([]);
/**
 * Where `alert_detail` returns to. The alarm is reachable from two places — the home
 * list's per-card strip and the identity screen's critical status panel — and a fixed
 * back path would eject the user out of the identity they were standing in.
 */
let alertReturnStep = $state<OnboardingStep>('home');
/**
 * Where `identity_detail` returns to — the same problem one tier up. An identity is now
 * reachable from the home list and from the Protection surface, and a fixed back path
 * would drop someone working through Protection's list back at the top of home.
 */
let identityReturnStep = $state<OnboardingStep>('home');

// ── Re-key (old-model upgrade) flow state ─────────────────────────────────
// The re-key runs against an existing identity; the review screen produces the new Share 3,
// which the backup screen then walks the user through saving before the staging teardown.
let rekeyDid = $state<string | null>(null);
let rekeyShare3 = $state('');
let rekeyShare3Words = $state('');
let rekeyBackupError = $state<string | null>(null);

// ── Self-held Shamir kit (escrow-less recovery key, MM-456) ──────────────────
let kitDid = $state<string | null>(null);
let kitShare2 = $state('');
let kitShare2Words = $state('');
let kitShare3 = $state('');
let kitShare3Words = $state('');
let kitBackupError = $state<string | null>(null);
/**
 * Whether the selected identity should be offered the escrow-less kit: its host answered
 * describeServer and advertised no `escrow`, or a kit is already mid-flight (which must be
 * finishable even if the host's answer changes underneath it).
 *
 * `null` while unknown, so the entry point is withheld rather than flickering in — a host
 * that could not be asked yields `reached: false` and no offer, which is the safe direction:
 * a Custos user wrongly offered this would land on a dead-end HOST_OFFERS_ESCROW screen.
 */
let kitOfferedForSelected = $state<boolean | null>(null);

// Fired unawaited per selection, so every write is gated on the DID still being the selected
// one. Selecting A then B before A resolves would otherwise show B the verdict computed for A
// — including offering the kit on an escrow-capable host, the exact dead end the `null` state
// exists to prevent.
async function resolveKitOffer(did: string, didDoc: Record<string, unknown>) {
  kitOfferedForSelected = null;
  try {
    const inProgress = await selfHeldKitInProgress(did);
    if (did !== selectedDid) return;
    if (inProgress) {
      kitOfferedForSelected = true;
      return;
    }
    const pdsUrl = extractPdsFromPlcDoc(didDoc);
    if (!pdsUrl) return;
    const capabilities = await getPdsCapabilities(pdsUrl);
    if (did !== selectedDid) return;
    kitOfferedForSelected = capabilities.reached && !capabilities.capabilities.includes('escrow');
  } catch (e) {
    console.warn('Self-held kit offer check failed:', e);
  }
}

let selectedRecoveryCid = $state<string | null>(null);
let selectedRecoveryCreatedAt = $state<string | null>(null);

// ── Recovery flow state ──────────────────────────────────────────────────
let recoveryCollected = $state<CollectedShare[]>([]);
// The NEW Share 3 produced by the rotation epilogue, for the backup walkthrough.
let recoveryShare3 = $state('');
let recoveryShare3Words = $state('');
// True when the epilogue screen was entered from launch-time resume (an app
// restart interrupted a prior recovery's share rotation).
let recoveryResuming = $state(false);
let recoveryBackupConfirmError = $state<string | null>(null);

// ── Migration flow state ──────────────────────────────────────────────────
// Each migration screen owns its own transient error/progress display; the page only threads
// the values a later screen consumes (destination + email for the flow, the result for success).
let migrationDid = $state('');
let migrationEmail = $state('');
let migrationInviteCode = $state<string | undefined>(undefined);
let migrationDestPds = $state('');
// Resolved source identity (from prepareMigration) for the source-auth screen's prefill + copy.
let migrationSourceHandle = $state('');
let migrationSourcePds = $state('');
let migrationResult = $state<ClaimResult | null>(null);

// ── Navigation helpers ───────────────────────────────────────────────────

function goTo(next: OnboardingStep) {
  errors = {};
  step = next;
}

// ── PDS configuration and OAuth event listener ──────────────────────

function handleVisibilityChange() {
  // Protection is included for the same reason home is, only more so: it is the surface
  // whose entire subject is how fresh the wallet's reading of the public record is, and
  // it would be the worst place to sit showing an hour-old one after a foreground.
  if (document.visibilityState === 'visible' && (step === 'home' || step === 'protection')) {
    checkIdentityStatus().catch((e) => {
      console.warn('PLC status check failed:', e);
    });
  }
}

onMount(async () => {
  // Resume a stranded removal first. If a prior removal deleted the PDS account but was
  // interrupted before the tombstone + local wipe finished (e.g. iOS killed the app
  // mid-flow), the identity still exists locally but its account is gone. Route straight
  // to the removal screen, which resumes the tombstone-only retry rather than the request
  // flow — the latter would fail against the already-deleted account.
  let resumingRemoval = false;
  try {
    const pending = await listPendingRemovals();
    if (pending.length > 0) {
      const did = pending[0];
      selectedDid = did;
      try {
        selectedDidDoc = await getStoredDidDoc(did);
      } catch {
        // The DID doc may already be gone (a wipe that outran its marker clear); the
        // removal screen still resumes correctly from the marker alone.
        selectedDidDoc = null;
      }
      selectedDeviceKeyIsRoot = null;
      step = 'remove_identity';
      resumingRemoval = true;
    }
  } catch (e) {
    console.warn('listPendingRemovals failed on mount:', e);
  }

  // Resume an interrupted recovery share-rotation epilogue next. The epilogue is
  // mandatory — the lost device's share world must be voided — so a restart lands
  // back on the epilogue screen, which re-runs only the incomplete steps.
  let resumingRecovery = false;
  if (!resumingRemoval) {
    try {
      const pendingEpilogue = await getPendingRecoveryEpilogue();
      if (pendingEpilogue) {
        recoveryResuming = true;
        step = 'recover_epilogue';
        resumingRecovery = true;
      }
    } catch (e) {
      console.warn('getPendingRecoveryEpilogue failed on mount:', e);
    }
  }

  // If the user has claimed identities, skip to home (unless we're resuming a removal
  // or a recovery epilogue).
  if (!resumingRemoval && !resumingRecovery) {
    try {
      const identities = await listIdentities();
      if (identities.length > 0) {
        step = 'home';
        // Opportunistic backup passes for opted-in identities: incremental and idempotent
        // by construction (content-addressed mirror / rev short-circuit), fire-and-forget so
        // the home screen never waits on them, and silent — failures surface the next time
        // the user opens the Media Backup screen. Media (blobs) and posts (repo CAR) are
        // independent opt-ins over the same iCloud location, so each runs on its own flag.
        for (const did of identities) {
          getBlobBackupStatus(did)
            .then((s) => (s.enabled ? runBlobBackup(did) : null))
            .catch((e) => {
              console.warn('opportunistic media backup pass failed:', did, e);
            });
          getRepoBackupStatus(did)
            .then((s) => (s.enabled ? runRepoBackup(did) : null))
            .catch((e) => {
              console.warn('opportunistic post backup pass failed:', did, e);
            });
        }
      }
    } catch (e) {
      console.error('listIdentities failed on mount:', e);
      // First launch (empty Keychain) or Keychain error — continue to mode_select
    }
  }

  // Legacy users (PDS URL configured but no managed-dids) stay at mode_select.
  // PdsConfigScreen internally checks for saved PDS URL, so the "Create new
  // identity" path handles them correctly without additional logic here.

  // Vestigial: the create flow no longer runs an OAuth round trip, so nothing emits this
  // on a fresh install. It still fires on relaunch for an install that completed the old
  // flow and left global OAuth tokens in the Keychain, where it lands on the same `home`
  // the listIdentities check above already chose. Retired with the rest of the wallet's
  // unused OAuth-client machinery.
  listen('auth_ready', () => {
    goTo('home');
  });
  // Note: We intentionally don't await listen() or return a cleanup function here.
  // Svelte 5's onMount does not await async cleanup return values (it would receive a
  // Promise, not the unlisten function). Since +page.svelte is the root page and never
  // unmounts during the app lifecycle, the listener persists for the app's lifetime,
  // which is the correct behavior.

  // PLC monitoring: check on app foreground
  document.addEventListener('visibilitychange', handleVisibilityChange);
});

onDestroy(() => {
  document.removeEventListener('visibilitychange', handleVisibilityChange);
});

