import { deriveIdentityPanelState } from './identity-status';
import type { IdentityStatus, UnauthorizedChange } from './ipc';

/**
 * Where the app should land when it opens or foregrounds while an identity is under
 * attack — the "emergencies interrupt; they are never destinations" rule made concrete.
 *
 * An alarm that waits behind navigation is an alarm the user reaches late, so the launch
 * decision resolves it rather than a badge. The counterweight is that the takeover is
 * *offered*, never locked in: every landing is dismissible, and a dismissed alarm does not
 * re-take the app on the next foreground. That is why the decision is a pure function of
 * (what the monitor found, what the user has already been shown) instead of a bare
 * "are there changes?" test — without the second half, backgrounding the app to look
 * something up would yank the user back into the same alarm on every return.
 */

/** Where the launch/foreground decision points. */
export type AlarmLanding =
  | { kind: 'none' }
  /** Exactly one identity in alarm: its own alarm surface, expanded. */
  | { kind: 'identity'; did: string; changes: UnauthorizedChange[] }
  /** More than one: the Protection surface, which already orders most-urgent-first. */
  | { kind: 'protection' };

/** An `AlarmLanding` plus the alarms it consumed, so the caller can mark them shown. */
export type AlarmLandingDecision = {
  landing: AlarmLanding;
  /** Keys to add to the dismissed set once the landing has been presented. */
  keys: string[];
};

/**
 * Identify an identity's alarm by its *content*, not just its DID.
 *
 * Dismissal has to survive a foreground without swallowing news. Keying on the DID alone
 * would mean a second, later unauthorized operation against an identity the user already
 * dismissed never interrupts again; keying on the change set means it does, because the
 * key changes the moment the monitor reports something new. CIDs are sorted so the key
 * does not depend on the order plc.directory happened to return the audit entries in.
 */
export function alarmKey(status: IdentityStatus): string {
  const cids = status.unauthorizedChanges.map((c) => c.cid).sort();
  return `${status.did}�${cids.join(',')}`;
}

/**
 * Decide where a launch or foreground should land, given the monitor's latest answer.
 *
 * An identity whose window has already expired still counts as an alarm. It has lost its
 * remedy, not its meaning — the identity is still being rewritten by a key the wallet does
 * not hold, and the alarm surface is where the wallet says so and explains what is left.
 * Suppressing it would leave the most serious state the app can report as the only one it
 * never volunteers. What keeps that from becoming a nag is the dismissal set, not a filter.
 */
export function decideAlarmLanding(
  statuses: IdentityStatus[],
  dismissed: ReadonlySet<string> = new Set()
): AlarmLandingDecision {
  const alarmed = statuses.filter((s) => s.unauthorizedChanges.length > 0);
  const fresh = alarmed.filter((s) => !dismissed.has(alarmKey(s)));

  if (fresh.length === 0) return { landing: { kind: 'none' }, keys: [] };

  // The landing is chosen from every live alarm, not only the undismissed ones: two
  // identities under attack are a Protection-surface situation even if the user has
  // already seen one of them, and dropping to a single identity's surface would quietly
  // hide the other. Which alarms were *new* decides whether we interrupt at all; how many
  // are *live* decides where interrupting takes you.
  const keys = fresh.map(alarmKey);

  if (alarmed.length === 1) {
    const only = alarmed[0];
    return {
      landing: { kind: 'identity', did: only.did, changes: only.unauthorizedChanges },
      keys,
    };
  }

  return { landing: { kind: 'protection' }, keys };
}

/**
 * The single most urgent alarm, for callers that need one identity out of many. Exported
 * for the same reason `compareRows` is: the ordering is a claim about severity, and a
 * second implementation of it is a second chance to disagree with Protection's list.
 */
export function mostUrgent(
  statuses: IdentityStatus[],
  now: number = Date.now()
): IdentityStatus | null {
  const alarmed = statuses.filter((s) => s.unauthorizedChanges.length > 0);
  if (alarmed.length === 0) return null;
  return alarmed.reduce((best, s) =>
    rank(s.unauthorizedChanges, now) > rank(best.unauthorizedChanges, now) ? s : best
  );
}

